import{_ as l,h as A,i as e,c as i,v as o,p as d,x as r,m as n,e as s,S as p}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"AdaLoRA","description":"","frontmatter":{"title":"AdaLoRA","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/adalora.md","filePath":"llm/adalora.md","lastUpdated":1788454257000}'),E={name:"llm/adalora.md"};function h(m,a,c,B,R,L){const t=A("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="adalora" tabindex="-1">AdaLoRA <a class="header-anchor" href="#adalora" aria-label="Permalink to &quot;AdaLoRA&quot;">​</a></h1><div class="epigraph"><p>同样多的秩预算，不该均匀洒在每一层、每一个奇异方向上；按对损失的贡献裁掉不重要的奇异值，把名额挪给真正在改任务的那些。</p><footer>—— Zhang 等，AdaLoRA: Adaptive Budget Allocation for Parameter-Efficient Fine-Tuning，ICLR 2023</footer></div><p>LoRA 给每个目标矩阵同一秩 \\(r\\)，等于事先假定所有层、所有方向同等重要。训练中很快能看到反例：靠近嵌入的投影与靠近输出的投影，需要的增量秩差一截；同一矩阵里，少数奇异方向扛了大部分损失下降，其余接近噪声。AdaLoRA 把增量写成可裁剪的参数化 SVD，训练过程中按重要性打分，动态分配全局秩预算：不重要的奇异值被置零，腾出的预算加到更重要的层或方向上。它解决的是「固定 \\(r\\) 的错配」，不是量化，也不是幅度–方向分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定秩有两头浪费。给不需要那么多方向的层一个大 \\(r\\)，优化器状态白占显存，还可能过拟合噪声方向。给真正需要容量的层一个小 \\(r\\)，任务相关更新被挤在过窄的子空间里，看起来像「LoRA 不如全参」，其实是预算放错地方。人工按层扫 \\(r\\) 的组合爆炸不可行：层数乘目标模块数，网格比训练本身还贵。</p><p>即使每层秩相同，层内也不是所有秩一分量等价。\\(BA\\) 的参数化并不正交，\\(A\\)、\\(B\\) 的行与列可以相互抵消，真实有效秩往往低于名义 \\(r\\)。要做动态分配，必须先有一套能指认「第几个方向值多少」的坐标。普通 LoRA 没有这套坐标。问题是：用什么参数化让方向可排序、用什么分数决定裁剪、如何在训练中途改秩而不把已学到的增量整段扔掉。</p><h3 id="名义秩与有效秩" tabindex="-1">名义秩与有效秩 <a class="header-anchor" href="#名义秩与有效秩" aria-label="Permalink to &quot;名义秩与有效秩&quot;">​</a></h3><p>\\(B\\) 与 \\(A\\) 同时训练时，它们可以学成近似低秩甚至列相关，名义 \\(r=8\\) 的适配器有效秩可能只有三四个。固定预算方法看不见这件事，只会继续给相关方向发学习率。动态方法若仍用 \\(BA\\) 而不正交化，重要性分数会把重复方向算成多个名额。因此 AdaLoRA 先换参数化，再谈分配。</p><p><span class="marginnote">动态分配的前提是全局预算固定。若总参数量可以任意涨，问题退回「再加一些 LoRA」；AdaLoRA 的主张是：在已经决定「只能训这么多参数」之后，把名额从死方向抽到活方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把第 \\(k\\) 个目标矩阵的增量写成三因子</p> \\[\\Delta W_k = P_k \\Lambda_k Q_k, \\]<p>其中 \\(\\Lambda_k\\) 是对角、存奇异值，\\(P_k\\)、\\(Q_k\\) 的列（行）在训练中被正交正则拉向半正交，近似 SVD 的左右奇异向量。可训练对象包括 \\(P\\)、\\(Q\\) 与对角元。每个对角元配一个重要性分数，典型形式结合该奇异值的幅度与它对损失的灵敏度（梯度信息），平滑后在全局排序。</p><p>训练分阶段。热身期允许较高的名义秩，让方向先被找到。之后进入剪裁：按分数丢掉最低的一批奇异值（对角元置零，对应的 \\(P\\)、\\(Q\\) 列不再更新），使全体非零奇异值个数逼近预先给定的预算 \\(b\\)。被剪掉的名额可以在后续步里重新分配给分数上升的层——实现上表现为：总非零个数不变，但非零落在哪些层、哪些序号上随时间移动。正交正则防止 \\(P\\)、\\(Q\\) 塌缩到彼此拷贝，否则分数无法对应独立方向。</p>',14)),(e(),d(p,null,{default:r(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%90%84%E5%B1%82%20%CE%94W%20%3D%20P%20%CE%9B%20Q%22%5D%20--%3E%20H%5B%22%E7%83%AD%E8%BA%AB%EF%BC%9A%E8%BE%83%E9%AB%98%E5%90%8D%E4%B9%89%E7%A7%A9%22%5D%0A%20%20H%20--%3E%20S%5B%22%E5%AF%B9%E5%A5%87%E5%BC%82%E5%80%BC%E6%89%93%E9%87%8D%E8%A6%81%E6%80%A7%E5%88%86%22%5D%0A%20%20S%20--%3E%20C%5B%22%E5%85%A8%E5%B1%80%E6%8E%92%E5%BA%8F%E5%B9%B6%E5%89%AA%E8%A3%81%22%5D%0A%20%20C%20--%3E%20R%5B%22%E9%A2%84%E7%AE%97%E8%BD%AC%E5%88%B0%E9%AB%98%E5%88%86%E6%96%B9%E5%90%91%22%5D%0A%20%20R%20--%3E%20S%0A%20%20C%20--%3E%20B%5B%22%E6%80%BB%E9%9D%9E%E9%9B%B6%E7%A7%A9%E9%80%BC%E8%BF%91%E9%A2%84%E7%AE%97%20b%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>Zhang 等人在 GLUE 与生成任务上显示：同样参数量下，自适应分配优于均匀 \\(r\\) 的 LoRA。收益来自分配，不是来自 SVD 本身比 \\(BA\\) 更强——若关掉剪裁、只保留三因子参数化，优势会小得多。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="分数为什么要幅度加灵敏度" tabindex="-1">分数为什么要幅度加灵敏度 <a class="header-anchor" href="#分数为什么要幅度加灵敏度" aria-label="Permalink to &quot;分数为什么要幅度加灵敏度&quot;">​</a></h3><p>只看奇异值大小，会留下「权重大但不影响当前损失」的方向，例如仍在复述预训练里无关的主轴。只看梯度，会把瞬时噪声方向抬得很高，剪裁振荡。二者相乘或加权，相当于问：这条方向既有能量、又在降低训练损失吗？平滑（移动平均）把分数从单步噪声里解开，使剪裁决策按百步而不是按迭代跳动。</p><p>正交正则的作用是可辨识性。没有它，\\(P\\Lambda Q\\) 可以任意插入旋转 \\(P\\leftarrow PR\\)、\\(\\Lambda\\) 不变、\\(Q\\leftarrow R^\\top Q\\)，分数与「第 \\(i\\) 个奇异值」的对应关系会漂。弱正则不求精确 SVD，只求列之间不要快速重混，让剪裁稳定。</p><p><span class="marginnote">剪裁是硬的：对角元变零后，该方向上的梯度也被挡住。若热身不够，过早剪掉的方向很难复活。预算 \\(b\\) 应低于热身名义秩，否则没有可挪动的名额，方法退化为带正交正则的 LoRA。</span></p><h3 id="与逐层手工设-的差别" tabindex="-1">与逐层手工设 \\(r\\) 的差别 <a class="header-anchor" href="#与逐层手工设-的差别" aria-label="Permalink to &quot;与逐层手工设 $r$ 的差别&quot;">​</a></h3><p>手工设 \\(r\\) 是静态先验：深浅层、注意力与 FFN，靠经验给不同整数。AdaLoRA 的分配是数据依赖的：换任务、换数据配比，名额会挪到另一组层。这更适合「同一基座、多种下游、每种只能训一次」的场景。代价是多一组超参：热身长度、剪裁间隔、正交系数、分数平滑。这些若乱设，动态分配的方差可以大过均匀 LoRA 的偏差。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>AdaLoRA 的实现比 LoRA 重：每层要维护 \\(P\\)、\\(Q\\)、\\(\\Lambda\\)、分数与掩码，检查点更大，合并进 \\(W_0\\) 前要把三因子乘回去。与 QLoRA 叠用时，被剪成零的方向仍可能占存储，除非实现真正释放对应列。许多开源训练脚本对 AdaLoRA 的支持弱于 LoRA，这是工程事实，不是方法无效。</p><p>动态秩改变计算图稀疏模式，吞吐不稳定，对大规模多卡并不总友善。若所有层的分数接近均匀，分配不会创造奇迹，只是多付正则与剪裁的成本。极小数据上，分数估计本身不可靠，均匀小 \\(r\\) 可能更稳。</p><p><span class="marginnote">不要把 AdaLoRA 的「自适应」理解成自动调学习率或自动选目标模块。它只在已经选中的那些矩阵内部、以及它们之间，挪奇异值名额。模块没打到的层，分数再高也分不到预算。</span></p><h3 id="与-dora、lora-的关系" tabindex="-1">与 DoRA、LoRA+ 的关系 <a class="header-anchor" href="#与-dora、lora-的关系" aria-label="Permalink to &quot;与 DoRA、LoRA+ 的关系&quot;">​</a></h3><p>DoRA 改的是幅度与方向的乘积几何，LoRA+ 改的是 \\(A\\)、\\(B\\) 的相对学习率，AdaLoRA 改的是秩在层与方向上的分配。三者回答不同的「LoRA 均匀性」假设。同时全开会让消融说不清是谁在起作用。合理顺序是：先用均匀 LoRA 确认任务可适配，再在仍缺容量或显存紧的时候，用 AdaLoRA 把固定预算花在刀刃上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AdaLoRA 用 \\(P\\Lambda Q\\) 参数化增量，使奇异方向可打分、可剪裁。</li><li>全局秩预算固定，训练中按重要性把名额从低分方向转到高分方向。</li><li>重要性结合奇异值幅度与损失灵敏度，并做时间平滑以免振荡。</li><li>正交正则维持方向可辨识，避免 SVD 因子任意旋转。</li><li>热身不足会过早砍掉有用方向；关掉剪裁则方法接近普通低秩。</li><li>实现与吞吐成本高于 LoRA；分数在小数据上不可靠。</li><li>出处：Zhang 等，<em>AdaLoRA: Adaptive Budget Allocation for Parameter-Efficient Fine-Tuning</em>，ICLR 2023。</li></ul>',16))])}const f=l(E,[["render",h]]);export{u as __pageData,f as default};
